-- Create Team Table
CREATE TABLE IF NOT EXISTS public.team (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    role TEXT NOT NULL,
    tier TEXT NOT NULL DEFAULT 'member',
    department TEXT NOT NULL DEFAULT 'Technical',
    photo_url TEXT,
    bio TEXT,
    email TEXT,
    linkedin TEXT,
    display_order INTEGER NOT NULL DEFAULT 100,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- RLS
ALTER TABLE public.team ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read access on team" ON public.team;
CREATE POLICY "Allow public read access on team" ON public.team FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public insert on team" ON public.team;
CREATE POLICY "Allow public insert on team" ON public.team FOR INSERT WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public update on team" ON public.team;
CREATE POLICY "Allow public update on team" ON public.team FOR UPDATE USING (true);

-- Clear existing to prevent duplicate seeding
DELETE FROM public.team;

